class FastArrayNegativeIndices {
    constructor() {
        this.a = [];
        this.b = [];
    }
    get(idx) {
        if (idx < 0) {
            idx = -idx - 1;
            return this.b[idx];
        }
        else {
            return this.a[idx];
        }
    }
    set(idx, value) {
        if (idx < 0) {
            idx = -idx - 1;
            this.b[idx] = value;
        }
        else {
            this.a[idx] = value;
        }
    }
}
